-- GENERATED by tools/gamekit/bundle.py from tools/gamekit/gamekit.lua and apps/lightsout/src/
-- -- edit those files, not this one.
local kit = (function()
-- gamekit: shared pieces for the API 2.9 puzzle games (Lights Out, Peg Solitaire, Nonograms,
-- Knight's Tour). tools/gamekit/bundle.py puts it in front of a game's src/main.lua as
-- `local kit = (function() ... end)()`, since the device has no require for package files.
--
--   kit.W, kit.H                      screen size
--   kit.font(name), kit.width(f, s), kit.line_h(name)
--   kit.short(s, n), kit.drop_last(s), kit.wrap(s, fname, maxw)
--   kit.read(name), kit.write(name, s), kit.kv(s)   ctx.storage helpers ("key=value" lines)
--   kit.now_ms(), kit.refresh()
--   kit.moved()                       count a move (a hook for a periodic full refresh; see below)
--   kit.key_accepted(ev)              side buttons send several events per press: keep one
--   kit.show(m), kit.close(), kit.modal()   a box over the screen: { title, lines, rows, cancel },
--                                     rows = { { {label, fn, enabled}, .. }, .. }
--   kit.draw_modal(gg), kit.tap_modal(x, y) -> true when the box took the tap
--   kit.button(gg, x, y, w, h, label, opts)  a framed button with a centred label
-- Every ctx.* function is a method on this API: colon calls everywhere. Nothing is filled black:
-- large black areas ghost on e-ink, and the host draws text black even when asked for white.

local kit = {}
kit.W, kit.H = 480, 800

function kit.font(name) return ctx.fonts and ctx.fonts[name] end
function kit.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
function kit.line_h(name)
  local ok, h = pcall(function() return kit.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

-- drop the last character (a whole UTF-8 sequence)
function kit.drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
function kit.short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end
-- word wrap on ASCII spaces only (%s may also match 0xA0, the second byte of some letters)
function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end
function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

-- e-ink full refresh: API 0.8 had ctx.display:full_refresh(); API 2.9 only offers
-- ctx:defer_full_refresh(n), which on the device (26102401) did not trigger one, and which by its
-- name may rather postpone the host's own periodic refresh. So nothing is asked for: the games
-- showed no ghosting problem without it. kit.moved() stays as the place to add one.
local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, BOX_W, ROW_H, GAP = 20, kit.W - 40, 56, 10
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function layout(m)
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

function kit.draw_modal(gg)
  local lines, btns, y, h = layout(modal)
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

return kit
end)()

-- Lights Out for XTOS Licorice, API 2.9 (uses tools/gamekit).
--
-- A 5x5 board of lights. Tapping a square switches it and its four neighbours; switch all of them
-- off. A lit square is a thick ring (no black fill: it ghosts on e-ink). Puzzles are made by
-- pressing random squares from the dark board, so every one can be solved; a solver over GF(2)
-- (Gaussian elimination on 25-bit masks, then the four solutions of the 2-dimensional null space)
-- gives the fewest presses, shown as the target, and drives Hint, which frames one square of an
-- optimal solution from the current position. Undo takes presses back. Saved after every press.

local W, H = kit.W, kit.H
local N = 5
local CELL, GX, GY = 84, 30, 150
local BTN_Y, BTN_H = 676, 60      -- below the board and two lines of text
local LEVELS = { { 'Easy', 4, 3 }, { 'Normal', 8, 6 }, { 'Hard', 13, 10 } }   -- name, presses, fewest at least

local board = 0          -- bit i (0-based, row-major) set = light i on
local moves, par = 0, 0
local history = {}       -- pressed squares, for Undo
local level = 2
local hint = nil         -- square to frame, or nil
local solved_count = 0
local msg = nil
local ERR = nil

------------------------------------------------------------------ rules

local function press_mask(i)
  local r, c = i // N, i % N
  local m = 1 << i
  if r > 0 then m = m | (1 << (i - N)) end
  if r < N - 1 then m = m | (1 << (i + N)) end
  if c > 0 then m = m | (1 << (i - 1)) end
  if c < N - 1 then m = m | (1 << (i + 1)) end
  return m
end

local function popcount(x)
  local n = 0
  while x ~= 0 do x = x & (x - 1); n = n + 1 end
  return n
end

-- the fewest presses that switch every light of b off (a bit mask of squares), or nil
local function solve(b)
  local rows = {}
  for j = 0, N * N - 1 do rows[j + 1] = { a = press_mask(j), b = (b >> j) & 1 } end   -- the press matrix is symmetric
  local piv, r = {}, 1
  for col = 0, N * N - 1 do
    local p
    for k = r, N * N do if (rows[k].a >> col) & 1 == 1 then p = k; break end end
    if p then
      rows[r], rows[p] = rows[p], rows[r]
      for k = 1, N * N do
        if k ~= r and (rows[k].a >> col) & 1 == 1 then
          rows[k].a = rows[k].a ~ rows[r].a
          rows[k].b = rows[k].b ~ rows[r].b
        end
      end
      piv[r] = col
      r = r + 1
    end
  end
  for k = r, N * N do if rows[k].a == 0 and rows[k].b == 1 then return nil end end
  local is_piv = {}
  for k = 1, r - 1 do is_piv[piv[k]] = true end
  local free = {}
  for col = 0, N * N - 1 do if not is_piv[col] then free[#free + 1] = col end end
  local best = nil
  for combo = 0, (1 << #free) - 1 do
    local x = 0
    for f = 1, #free do if (combo >> (f - 1)) & 1 == 1 then x = x | (1 << free[f]) end end
    for k = 1, r - 1 do
      local v = rows[k].b ~ (popcount(rows[k].a & ~(1 << piv[k]) & x) & 1)
      if v == 1 then x = x | (1 << piv[k]) end
    end
    if not best or popcount(x) < popcount(best) then best = x end
  end
  return best
end

------------------------------------------------------------------ storage

local function save()
  kit.write('game.txt', 'board=' .. board .. '\nmoves=' .. moves .. '\npar=' .. par .. '\nlevel=' .. level ..
    '\nsolved=' .. solved_count .. '\nhistory=' .. table.concat(history, ','))
end

local function new_puzzle()
  local lv = LEVELS[level]
  repeat
    local b, pressed = 0, {}
    while #pressed < lv[2] do
      local i = math.random(0, N * N - 1)
      if not pressed[i] then pressed[i] = true; pressed[#pressed + 1] = i; b = b ~ press_mask(i) end
    end
    board = b
    par = popcount(solve(board) or 0)
  until par >= lv[3]
  moves, history, hint, msg = 0, {}, nil, nil
  save()
end

local function load()
  local t = kit.kv(kit.read('game.txt'))
  level = math.max(1, math.min(#LEVELS, tonumber(t.level) or 2))
  solved_count = tonumber(t.solved) or 0
  if not t.board then new_puzzle(); return end
  board, moves, par = tonumber(t.board) or 0, tonumber(t.moves) or 0, tonumber(t.par) or 0
  history = {}
  for v in (t.history or ''):gmatch('%d+') do history[#history + 1] = tonumber(v) end
  if board == 0 then new_puzzle() end
end

------------------------------------------------------------------ actions

local function press(i)
  if board == 0 then return end
  board = board ~ press_mask(i)
  moves = moves + 1
  history[#history + 1] = i
  hint, msg = nil, nil
  kit.moved()
  if board == 0 then
    solved_count = solved_count + 1
    local at = moves <= par
    kit.show({
      title = 'All lights are off!',
      lines = { 'Moves: ' .. moves .. '    Target: ' .. par, at and 'You matched the fewest presses.' or 'It can be done in ' .. par .. '.' },
      rows = { { { 'New', function() kit.close(); new_puzzle() end }, { 'Close', kit.close } } },
      cancel = kit.close,
    })
  end
  save()
end

local function undo()
  local i = table.remove(history)
  if not i then msg = 'Nothing to undo.'; return end
  board = board ~ press_mask(i)
  moves = math.max(0, moves - 1)     -- the press is taken back
  hint = nil
  save()
end

local function show_hint()
  if board == 0 then return end
  local x = solve(board)
  if not x or x == 0 then return end
  for i = 0, N * N - 1 do if (x >> i) & 1 == 1 then hint = i; break end end
  msg = 'Hint: press the framed square.'
end

------------------------------------------------------------------ drawing

local BUTTONS = {
  { function() return 'New' end, function() new_puzzle() end },
  { function() return 'Undo' end, undo },
  { function() return 'Hint' end, show_hint },
  { function() return LEVELS[level][1] end, function()
      level = level % #LEVELS + 1
      msg = LEVELS[level][1] .. ': from the next New puzzle.'
      save()
    end },
}
local function button_rect(k)
  local bw = math.floor((W - 24 - 3 * 8) / 4)
  return 12 + (k - 1) * (bw + 8), BTN_Y, bw, BTN_H
end

local function ring(gg, cx, cy, r)
  for o = 0, 3 do pcall(function() gg:circle(cx, cy, r - o) end) end
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    gg:text(16, 14, 'Lights Out', { font = kit.font('large') })
    gg:text(16, 58, 'Moves ' .. moves .. '    Target ' .. par .. '    ' .. LEVELS[level][1], { font = kit.font('medium') })
    gg:text(16, 92, 'Solved: ' .. solved_count, { font = kit.font('small') })
    gg:line(0, 130, W, 130)
    if kit.modal() then kit.draw_modal(gg); return end
    for i = 0, N * N - 1 do
      local x, y = GX + (i % N) * CELL, GY + (i // N) * CELL
      gg:rect(x + 3, y + 3, CELL - 6, CELL - 6, { line_width = 2 })
      if (board >> i) & 1 == 1 then
        ring(gg, x + CELL // 2, y + CELL // 2, 28)
        ring(gg, x + CELL // 2, y + CELL // 2, 12)
      end
      if hint == i then                       -- corner brackets
        for _k, d in ipairs({ { 8, 8, 1, 1 }, { CELL - 8, 8, -1, 1 }, { 8, CELL - 8, 1, -1 }, { CELL - 8, CELL - 8, -1, -1 } }) do
          for o = 0, 2 do
            gg:line(x + d[1], y + d[2] + o * d[4], x + d[1] + 16 * d[3], y + d[2] + o * d[4])
            gg:line(x + d[1] + o * d[3], y + d[2], x + d[1] + o * d[3], y + d[2] + 16 * d[4])
          end
        end
      end
    end
    local m = msg or 'Tap a square: it and its neighbours switch. Switch them all off.'
    local lh = kit.line_h('small') + 4
    for k, l in ipairs(kit.wrap(m, 'small', W - 32)) do
      if k <= 2 then gg:text(16, GY + N * CELL + 14 + (k - 1) * lh, l, { font = kit.font('small') }) end
    end
    for k, b in ipairs(BUTTONS) do
      local x, y, bw, bh = button_rect(k)
      kit.button(gg, x, y, bw, bh, b[1]())
    end
    if ERR then gg:text(16, H - 30, kit.short('ERR ' .. ERR, 48), { font = kit.font('small') }) end
  end)
  if not ok then pcall(function() gg:text(8, H - 60, kit.short('draw ERR ' .. tostring(e), 46)) end) end
end

function on_input(c, ev)
  ERR = nil
  local ok, e = pcall(function()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' and ev.phase == 'up' then
      local x, y = ev.x or 0, ev.y or 0
      if kit.tap_modal(x, y) then return end
      for k, b in ipairs(BUTTONS) do
        local bx, by, bw, bh = button_rect(k)
        if x >= bx and x < bx + bw and y >= by and y < by + bh then b[2](); return end
      end
      if x >= GX and x < GX + N * CELL and y >= GY and y < GY + N * CELL then
        press(((y - GY) // CELL) * N + (x - GX) // CELL)
      end
    elseif ev.type == 'key' and kit.key_accepted(ev) and ev.key == 'back' and kit.modal() and kit.modal().cancel then
      kit.modal().cancel()
    end
  end)
  if not ok then ERR = tostring(e) end
  kit.refresh()
  return true
end

function on_load(c)
  math.randomseed(kit.now_ms() or 1)
  load()
end

function on_leave() save() end

if rawget(_G, '__TEST') then
  __TEST.api = { solve = solve, press_mask = press_mask, popcount = popcount,
                 state = function() return board, moves, par, level end,
                 set = function(b, p) board, par, moves, history = b, p, 0, {} end }
end
